// Plain PHP: knows nothing about any cloud, so it runs anywhere
final readonly class InvoiceThumbnailer
{
    public function __construct(private FilesystemOperator $storage) {}

    public function thumbnail(string $path): string
    {
        $image = (new ImageManager(new Driver()))->read($this->storage->read($path));
        $small = $path.'.thumb.jpg';
        $this->storage->write($small, (string) $image->scaleDown(width: 400)->toJpeg());

        return $small;
    }
}

// The only Lambda-specific file (Bref): a thin handler that calls it
final readonly class ResizeHandler implements Handler
{
    public function __construct(private InvoiceThumbnailer $thumbnailer) {}

    public function handle(mixed $event, Context $context): array
    {
        return ['thumbnail' => $this->thumbnailer->thumbnail($event['path'])];
    }
}

