-- BAD, one release: the new code expects phone_e164, the old code expects phone.
ALTER TABLE customer RENAME COLUMN phone TO phone_e164;
-- Roll the code back and the old code fails on a column that no longer exists.

-- GOOD, release 1 (expand): add the new column, keep the old one, write to both.
ALTER TABLE customer ADD phone_e164 VARCHAR(20) NULL;
-- Rolling back to the earlier code is safe: it just ignores the new column.

-- GOOD, release 2: copy old rows over in batches, and read only phone_e164.

-- GOOD, release 3 (contract): no running code uses phone any more, so drop it.
ALTER TABLE customer DROP COLUMN phone;

