public function answer(string $question): string
{
    $policy = $this->policies->text('refunds'); // our real text: "within 3 days"

    $system = <<<PROMPT
        You are a support assistant for an online shop.
        Answer ONLY from the policy between the <policy> tags.
        If the policy does not answer the question, reply exactly: NOT_IN_POLICY
        Otherwise quote the policy sentence you used.
        <policy>
        $policy
        </policy>
        PROMPT;

    $reply = $this->llm->ask($system, $this->redactor->redact($question));

    return str_contains($reply, 'NOT_IN_POLICY')
        ? $this->handOffToHuman($question)
        : $reply;
}

final class TicketClassifier
{
    public function __construct(
        private readonly HttpClientInterface $llmClient,
        private readonly PiiRedactor $redactor,
        private readonly TicketCategoryParser $parser,
        private readonly LoggerInterface $logger,
        #[Autowire('%env(LLM_MODEL)%')] private readonly string $model,
    ) {
    }

    public function classify(string $text): TicketCategory
    {
        try {
            $data = $this->llmClient->request('POST', '/v1/messages', ['json' => [
                'model' => $this->model,
                'max_tokens' => 50,
                'temperature' => 0,
                'system' => self::SYSTEM_PROMPT,
                'messages' => [['role' => 'user',
                    'content' => '<ticket>'.$this->redactor->redact($text).'</ticket>']],
            ]])->toArray();

            return $this->parser->parse($data['content'][0]['text'] ?? '');
        } catch (\Throwable $e) {
            $this->logger->warning('llm.classify_failed', ['exception' => $e]);

            return TicketCategory::Other; // fallback: goes to the general queue
        }
    }
}

enum TicketCategory: string
{
    case Billing = 'billing';
    case Delivery = 'delivery';
    case Other = 'other';
}

final class TicketCategoryParser
{
    public function parse(string $raw): TicketCategory
    {
        $data = json_decode($raw, true, 4, JSON_THROW_ON_ERROR);

        // don't trust the model: accept only known values
        $category = TicketCategory::tryFrom($data['category'] ?? '');

        if (null === $category) {
            throw new \UnexpectedValueException('Unknown category from LLM');
        }

        return $category;
    }
}

final class PiiRedactor
{
    private const PATTERNS = [
        '/[\w.+-]+@[\w-]+\.[\w.]+/' => '[EMAIL]',
        '/(?<!\d)(?:\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4}(?!\d)/' => '[PHONE]',
        '/\b\d{13,19}\b/' => '[CARD]',
    ];

    public function redact(string $text): string
    {
        $keys = array_keys(self::PATTERNS);

        return preg_replace($keys, array_values(self::PATTERNS), $text) ?? '';
    }
}

#[Group('llm-eval')] // not on every push: every call costs money
final class TicketClassifierEvalTest extends KernelTestCase
{
    public function testAccuracyStaysAboveThreshold(): void
    {
        $classifier = self::getContainer()->get(TicketClassifier::class);
        $lines = file(__DIR__.'/golden/tickets.jsonl', FILE_IGNORE_NEW_LINES);
        $correct = 0;

        foreach ($lines as $line) {
            $row = json_decode($line, true, 4, JSON_THROW_ON_ERROR);

            if ($classifier->classify($row['text'])->value === $row['label']) {
                ++$correct;
            }
        }

        $accuracy = $correct / count($lines);
        self::assertGreaterThanOrEqual(0.90, $accuracy, "accuracy: $accuracy");
    }
}

